{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Healthcare Research Data",
    "url": "http://localhost:7808",
    "widgets_json": {
      "pipeline_vegalite": {
        "name": "Pipeline Mix (Vega-Lite)",
        "description": "Vega-Lite bar spec of pipeline phase mix.",
        "endpoint": "/pipeline-vegalite",
        "type": "chart-vegalite",
        "w": 20,
        "h": 9
      },
      "trial_catalysts": {
        "name": "Trial Catalysts",
        "description": "Upcoming clinical trial readouts.",
        "endpoint": "/trial-catalysts",
        "type": "table",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "ticker",
            "type": "endpoint",
            "label": "Ticker",
            "optionsEndpoint": "/tickers",
            "value": "PFE"
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "ticker",
                "headerName": "Ticker",
                "cellDataType": "text"
              },
              {
                "field": "phase",
                "headerName": "Phase",
                "cellDataType": "text"
              },
              {
                "field": "readout_date",
                "headerName": "Readout",
                "cellDataType": "dateString"
              }
            ]
          }
        }
      },
      "catalyst_metric": {
        "name": "Catalysts 30d",
        "description": "Catalysts in the next 30 days.",
        "endpoint": "/catalyst-count",
        "type": "metric",
        "w": 6,
        "h": 4
      }
    },
    "apps_json": [
      {
        "name": "Pipeline Chart Room",
        "tabs": [
          {
            "id": "pipeline",
            "name": "Pipeline",
            "layout": [
              {
                "i": "pipeline_vegalite",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              },
              {
                "i": "catalyst_metric",
                "x": 20,
                "y": 0,
                "w": 6,
                "h": 4
              }
            ],
            "description": "Pipeline chart, trials, and catalyst count."
          },
          {
            "id": "trials",
            "name": "Trials",
            "layout": [
              {
                "i": "trial_catalysts",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ],
            "groups": [
              {
                "name": "Pipeline Sync",
                "type": "param",
                "paramName": "pipeline_ticker",
                "widgetIds": [
                  "pipeline_vegalite",
                  "trial_catalysts"
                ]
              }
            ]
          }
        ]
      }
    ]
  }
}

